INSERT INTO "public"."fishing_spots" ("id", "user_id", "creator_name", "title", "description", "lat", "lng", "image_url", "created_at") VALUES ('06166a37-7e60-441b-9cf3-a9cbf5bfbd9a', null, 'Abant Sevdalısı', 'Abant Gölü Batı Kıyısı (Bolu)', 'Endemik Abant Alabalığı (Salmo abanticus) avcılığının merkezi. Fly fishing veya micro LRF kaşıkları ile avcılık yapılmaktadır.', 40.6053, 31.2811, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('067dafea-879d-4a97-a27f-3f56b1d05c53', null, 'Seyhan Yayın Kulübü', 'Adana Seyhan Baraj Gölü', 'Adananın dev tatlı su gölü. Canlı yemli düzenekler ile 50kg+ dev Yayın Balığı, boilie yemlerle trofe Aynalı Sazan ve Tatlı Su Kefali yakalanır.', 37.045, 35.328, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('089e3f78-c94c-43e1-9ab6-b035e27dcb08', null, 'Tortum Alabalık Koyu', 'Tortum Gölü & Tortum Şelalesi Ağzı (Erzurum)', 'Erzurumun meşhur doğal gölü. Micro LRF kaşıkları ve sinek olta (Fly Fishing) ile Kırmızı Benekli Alabalık ve Tatlı Su Kefali avlanır.', 40.642, 41.562, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('0a8c3a50-ae92-4e19-bd83-4d8e54f13870', null, 'Sivas Trofe Ekibi', 'Sivas Gölova Baraj Gölü', 'Sivas bölgesinin trofe sazan merkezi. Özel boilie yemler ve dip düzenekleri ile trofe Aynalı Sazan ve Tatlı Su Kefali avlanır.', 40.062, 38.614, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('0b028f40-f5be-4a77-a36b-9c0a174ac6a2', null, 'Vanlı Kaptan', 'Van Gölü Tatlı Su Dere Ağzı (Van)', 'Van gölüne dökülen derelerin birleşim noktası. Meşhur İnci Kefalı geçiş koridorudur. Tatlı su ile sodalı suyun birleştiği dere ağızlarında av sezonunda zengin av verir.', 38.521, 43.342, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('0bbaa972-be31-4468-a7b5-0016b9feca54', null, 'Dicle Sevdalısı', 'Diyarbakır Kralkızı Baraj Gölü (Dicle)', 'Diyarbakırın en büyük su rezervuarı. Dip olta takımları ile Şabut Balığı, trofe Aynalı Sazan ve Fırat Turnası avlanır.', 38.345, 40.021, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('0da8b3fb-c873-4eca-b9f0-1f4cbbe45ad0', null, 'Manavgat Nehir Olta', 'Antalya Manavgat Nehir Ağzı & Deniz Birleşimi', 'Manavgat şelalesinin Akdenize birleştiği nokta. Spin silikon sahteler ile trofe Deniz Levreği, Yılan Balığı ve nehir içlerinde Yayın alır.', 36.735, 31.458, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('1033d055-01f8-4360-8df0-56b82a858776', null, 'Kıyı Oltacısı', 'Şile Liman Arkası Kayalıklar', 'Levrek ve eşkina için harika bir gece merasıdır. Yemli karides ve boru kurdu çalışır.', 41.1764, 29.6105, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:00:56.874983+00'), ('19670c71-e36b-4df5-8aa8-f8aa271745a9', null, 'Manisa Baraj Avcısı', 'Manisa Demirköprü Baraj Gölü', 'Geniş tatlı su rezervuarı. Boilie mısır montajları ile Aynalı Sazan, canlı ve sülük yemle trofe Yayın Balığı avlanır.', 38.612, 28.385, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('1a6f9e5c-2f46-4754-8e5c-c918dc07d46a', null, 'Caner Balıkçı', 'Galata Köprüsü Haliç Tarafı', 'Çinekop ve istavrit avı için klasiktir. Akşam saatlerinde çapari oldukça verimlidir.', 41.02, 28.9731, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:00:56.874983+00'), ('1cadc869-2c96-48eb-828e-5ccde622ce5b', null, 'Gaziantep Baraj Grubu', 'Gaziantep Karkamış Baraj Gölü', 'Fırat nehrinin sınır barajı. Hamur, mısır ve özel dip montajları ile trofe Sazan, sahte balıklarla Fırat Turnası yakalanır.', 36.842, 38.012, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('1fdf11d3-6d73-4eaf-b5a1-57dc892310fe', null, 'Marmaraereğlisi Olta', 'Tekirdağ Marmaraereğlisi Liman Mendireği', 'Tekirdağ bölgesinin klasik mera noktası. Surfcasting dip olta takımları ile Mırmır, Çupra, Zargana ve gece eşkina yapar.', 40.967, 27.958, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('2087baef-4eb6-4496-aa74-596334104ae8', null, 'Didim Olta Koyu', 'Aydın Didim Taşburnu Liman Sahili', 'Kumluk geniş mera alanı. Kıyıdan surfcast dip atışları ile Mırmır, Levrek ve trofe Çupra verir.', 37.345, 27.231, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('2208b4e4-2066-43c3-868e-fa345826cc79', null, 'Işıklı Turna Sevdası', 'Işıklı Gölü Kıyısı & Nilüfer Tarlaları (Denizli / Afyon)', 'Nilüfer çiçekleriyle kaplı su üstü turna cenneti. Su üstü kurbağa sahteleri ve kaşıklar ile trofe Turna Balığı (Northern Pike) çekilir.', 38.242, 29.912, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('24919e3c-fd2a-46cb-835e-bf61f0cd981b', null, 'Ardahan Olta Kulübü', 'Çıldır Gölü Kıyısı & Buz Üstü Avı (Ardahan / Kars)', 'Türkiyenin en yüksek irtifa dev gölü. Kışın donan 1 metre buz üzerinde delik açılarak Sarı Balık (Sazan) ve Alabalık, yazın dip oltasıyla trofe Sazan alınır.', 41.042, 43.255, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('26a7d5f6-6a8f-4eae-acf4-6af4c495715d', null, 'Caner Balıkçı', 'Galata Köprüsü Haliç Tarafı', 'Çinekop ve istavrit avı için klasiktir. Akşam saatlerinde çapari oldukça verimlidir.', 41.02, 28.9731, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:30:39.954133+00'), ('275f6c10-f926-4357-a639-7214975c52da', null, 'Samandağ Sahil Olta', 'Hatay Samandağ Sahil Şeridi', 'Türkiyenin en uzun sahil şeritlerinden biri. Surfcast dip oltaları ile kışın Kalkan, baharda Mırmır, Çupra ve Spin ile Levrek yakalanır.', 36.082, 35.924, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('2ae86a57-335c-488c-b4e1-b9e0f7b8b133', null, 'Ahmet Yılmaz', 'Sarayburnu Akıntı Burnu', 'İstavrit ve lüfer için Boğazın en verimli meralarından biridir. Ağır kurşun arkası rapala tavsiye edilir.', 41.0175, 28.9833, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:33:33.878912+00'), ('32edd30f-795a-411b-b354-9f4f1830e651', null, 'Manyas Turna Olta', 'Manyas (Kuş) Gölü Kıyısı (Balıkesir)', 'Kuş cenneti çevresindeki sazlık mera. Maket balıklarla Turna, dip takımlarıyla Yayın ve Sazan avlanır.', 40.198, 27.965, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('330ecc97-834e-45c3-97de-da9af05a960f', null, 'Karadeniz Kıyıcısı', 'Akçakoca Çuhallı Plajı Kayalıkları (Düzce)', 'Kumluk ve kırmalık dip yapısı. İlkbahar ve kış aylarında yemli boru kurdu ve taze istavrit yaprağı ile trofe Kalkan ve Zargana avı için ideal mera.', 41.0835, 31.129, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('361439b3-cc14-4f4b-ac85-6811a3f22df9', null, 'Uluabat Sevdalısı', 'Bursa Uluabat (Apolyont) Gölü', 'Zengin sazlık yapısı. Botla ve kıyıdan sahte balık at-çek ile Turna, boilie mısır düzenekleri ile Aynalı Sazan avcılığı merkezi.', 40.185, 28.602, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('394cc61b-608e-4ed7-9a8a-e3050c0a7cae', null, 'Kızkalesi Sevdalısı', 'Mersin Kızkalesi Sahil Kırmalığı', 'Kumluk ve kırk kayalık geçiş hattı. Surfcast takımlar ile Mırmır, Çupra, Levrek ve kışın kalamar avı yapılır.', 36.462, 34.145, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('3f7ca4a2-af43-4a9c-a8eb-fbfd630cce63', null, 'Faroz Balıkçısı', 'Trabzon Faroz Balıkçı Barınağı Mendireği', 'Doğu Karadeniz balıkçılığının kalbi. Palamut, çinekop, zargana ve iribaş istavrit avcılığında bölgenin 1 numaralı merasıdır.', 41.006, 39.705, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('41092195-4cf0-493e-a10a-cc5c24e2aefc', null, 'Fethiye Av Grubu', 'Muğla Fethiye Ölüdeniz & Gemiler Koyu Kayalıkları', 'Berrak ve derin akıntılı sular. Kıyıdan jiggıng ile Akya, zoka yemli düzeneklerle Kalamar ve Melanur avcılığı yaygındır.', 36.551, 29.112, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('45711202-37af-4469-82e8-3d91386f25ee', null, 'Erdek Olta Kulübü', 'Balıkesir Erdek Çuğra Plajı Kayalıkları', 'Kapıdağ Yarımadasının en zengin meralarından biri. Yemli kayalık dip takımı ile trofe Çupra, Mırmır, Eşkina ve Kalamar alınır.', 40.402, 27.785, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('474d50d4-f267-4a1e-a709-d682f47949d6', null, 'Menzelet Baraj Olta', 'Menzelet Baraj Gölü (Kahramanmaraş)', 'Kanyon tipinde derin tatlı su rezervuarı. Bot ve kıyıdan sahte yemlerle Alabalık, canlı yemle dev Yayın balığı ve Sazan alınır.', 37.685, 36.852, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('48011f07-1003-4ec6-85e8-96970fb101e7', null, 'Filyos Balıkçısı', 'Zonguldak Filyos Liman Mendireği', 'Batı Karadenizin derin liman merası. Sonbahar aylarında palamut ve lüfer akınında kaşık ve çapari ile yüksek verim sağlar.', 41.572, 32.025, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('482e9b07-b683-4e94-a6f1-d5fc40adf0c6', null, 'Fırat Turnası Avcısı', 'Atatürk Baraj Gölü Bozova Sahili (Şanlıurfa)', 'Güneydoğunun deniz lakaplı dev iç suyu. Efsanevi dev Fırat Turnası (Luciobarbus esocinus), Şabut Balığı ve Trofe Aynalı Sazan merkezidir.', 37.365, 38.521, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('487a5111-7f4d-4512-9251-f56975cc914e', null, 'Kesikköprü Grubu', 'Ankara Kesikköprü Baraj Gölü (Kızılırmak)', 'Kızılırmak üzerindeki kanyon barajı. Şamandıralı ve silikon sahteler ile Alabalık, Sudak ve Yayın balığı avı yapılır.', 39.382, 33.435, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('52e50072-3030-4338-8103-534cf6693f6f', null, 'Eğirdir Sudak Grubu', 'Eğirdir Gölü Yeşil Ada Sahili (Isparta)', 'Türkiyenin en iyi Sudak (Dişli Balık) merası. Silikon maket balıklar ve canlı gümüş yemleri ile iri Sudak ve Aynalı Sazan yakalanır.', 37.876, 30.852, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('55c54dc6-6434-48c3-ba9a-198e8628ac6d', null, 'Çanakkale Boğaz Reis', 'Çanakkale Boğazı Kilitbahir Kıyıları', 'Çanakkale Boğazının derin ve akıntılı suları. Ağır sırtı (Trolling), jigging ve uzun olta ile trofe Akya, Lüfer, Palamut ve Levrek merasıdır.', 40.147, 26.379, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('585b473c-98ee-4c38-b24d-4a676097d448', null, 'Yamula Baraj Kaptan', 'Kayseri Yamula Baraj Gölü (Kızılırmak)', 'Kayserinin deniz lakaplı dev barajı. Kaşık ve döner kaşıkla Gökkuşağı Alabalığı, silikon sahteler ile Sudak ve Sazan avı verimlidir.', 38.892, 35.284, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('5aceed83-08a3-41d3-8e43-dcb3127ee0be', null, 'Mudanya Kıyı Olta', 'Bursa Mudanya Güzelyalı Mendireği', 'Gemlik körfezi çıkışı. LRF silikonları ile istavrit ve mırmır, silikon sahteler ile kışın Deniz Levreği ve Kalamar avı çok popülerdir.', 40.366, 28.912, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('5b56599c-49c2-43df-8c22-e13ee8027930', null, 'Sapanca Olta Kulübü', 'Sapanca Gölü Kırkpınar Sahili (Sakarya)', 'Göl çevresindeki en sakin ve verimli tatlı su merası. Mısır ve boilie düzenekleri ile trofe Sazan, sahte maket balıklar ile Turna avı yapılır.', 40.6935, 30.281, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('5e75351a-187e-468d-ab2d-662faa7e7382', null, 'Dikili Balıkçısı', 'İzmir Dikili Bademli Sahil Kırmalığı', 'Kuzey Egenin temiz ve sakin suları. Surfcasting olta takımları ile Mırmır, Çupra ve gece kalamar avcılığı yoğun yapılır.', 39.025, 26.834, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('5e98e3df-0c88-4d66-a4f3-0b670e87ae0a', null, 'Adıyaman Kahta Kıyısı', 'Atatürk Barajı Kahta Sahili (Adıyaman)', 'Adıyaman bölgesinin zengin tatlı su mera alanı. Kaşık ve canlı yemli dip montajları ile Fırat Turnası, Sazan ve Yayın Balığı avlanır.', 37.745, 38.642, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('640248ae-d98d-42de-9ae6-a679d10466e2', null, 'Kaptan Ahmet', 'Akçakoca Liman Mendirek (Düzce)', 'Karadeniz lüfer ve palamut geçişinin Akçakoca mendirek ucu ana merkezidir. Sonbaharda kurşun arkası sahte ve silikon yemle zengin istavrit, çinekop ve palamut yapar.', 41.0872, 31.1165, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('678710b0-2a70-4cd6-b914-92eefe649039', null, 'Beyşehir Sevdalısı', 'Konya Beyşehir Gölü Kubbeli Sahili', 'Türkiyenin en büyük tatlı su gölü. Silikon yemlerle Sudak (Akbalık), küspeli dip takımları ile Aynalı Sazan ve Tatlı Su Kefali avlanır.', 37.678, 31.721, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('6f63ebbb-f8b5-4ef7-b4cd-f7a726282f1a', null, 'Bodrum Kıyıcısı', 'Muğla Bodrum Yalıkavak Mendirek Ucu', 'Güney Egenin derin mavi suları. Gezer kurşunlu yemli dip takımları ile Çupra, Sargoz ve tekne arkası trolling ile Akya ve Lagos hedeflenir.', 37.106, 27.291, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('75ea5f1e-d524-459f-b175-a78b164c2289', null, 'Kefken Sevdalısı', 'Kocaeli Kefken Pembe Kayalar', 'Karadenizin doğal kayalık kanyon merası. Spin sahteler ile trofe Deniz Levreği, gece yemli canlı boru kurdu ile Eşkina ve Karagöz alınır.', 41.181, 30.198, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('7813f158-3577-4b17-893b-4e2a451453f5', null, 'Ahmet Yılmaz', 'Sarayburnu Akıntı Burnu', 'İstavrit ve lüfer için Boğazın en verimli meralarından biridir. Ağır kurşun arkası rapala tavsiye edilir.', 41.0175, 28.9833, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 08:41:47.904397+00'), ('7a125590-1b2a-4a02-95c3-a788dfe99270', null, 'İskenderun Reis', 'Hatay İskenderun Balıkçı Barınağı Mendireği', 'Doğu Akdeniz Körfezi liman ağzı. Şamandıralı ve gezer kurşunlu takımlarla Lagos, Çupra, Akya ve su üstü maketlerle Baracuda avı yapılır.', 36.592, 36.175, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('7b06c92e-5bdf-4eec-8cdf-6279d8977930', null, 'Çarşamba Nehir Olta', 'Samsun Çarşamba Yeşilırmak Ağzı & Sahil', 'Yeşilırmağın Karadenize döküldüğü besin değeri yüksek alandır. Spin silikon sahteler ile Kalkan, Deniz Levreği ve Nehir Yayın balığı çıkar.', 41.382, 36.635, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('7e9de8a9-de4d-4076-990b-c3a55d22ff09', null, 'Ahmet Yılmaz', 'Sarayburnu Akıntı Burnu', 'İstavrit ve lüfer için Boğazın en verimli meralarından biridir. Ağır kurşun arkası rapala tavsiye edilir.', 41.0175, 28.9833, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:00:56.874983+00'), ('8327db86-734d-4ec7-bf78-342339904244', null, 'Terkos Avcısı', 'İstanbul Terkos (Durusu) Gölü', 'İstanbulun en büyük tatlı su av merası. İlkbahar ve sonbahar aylarında maket balıklar ve kaşıklar ile trofe Turna, Yayın ve Sazan avı yapılır.', 41.332, 28.675, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('83fb4fee-bffe-42b4-b16e-566e6b60b792', null, 'Başkent Sazancı', 'Ankara Hirfanlı Baraj Gölü (Kırşehir Sınırı)', 'İç Anadolunun en büyük sazan ve sudak merası. Botla ve kıyıdan uzun mesafeli atışlarla dev Aynalı Sazan, Sudak ve Yayın yakalanır.', 39.264, 33.521, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('84c7e813-1fd6-4bd1-a1d0-d0c836e1e917', null, 'Kıyı Oltacısı', 'Şile Liman Arkası Kayalıklar', 'Levrek ve eşkina için harika bir gece merasıdır. Yemli karides ve boru kurdu çalışır.', 41.1764, 29.6105, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 08:41:47.904397+00'), ('86fbbecb-71b4-43d0-ac31-9ff6515203cb', null, 'Mardin Nehir Kaptan', 'Mardin Ilısu Baraj Gölü (Dicle Nehri)', 'Dicle nehri kanyon vadisi. Canlı yem ve ağır kaşıklarla dev Fırat Turnası, Mezopotamya Yayın balığı ve Şabut hedeflenir.', 37.542, 41.725, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('8b40f155-3cd6-4f75-ad0f-dab998c7fccb', null, 'Giresun Liman Kıyısı', 'Giresun Liman Ağzı Kayalıkları', 'Derin kırmalık yapı. Gece tavuk göğsü ve hamsi yemli dip takımları ile Çinekop, Eşkina ve iri Mezgit avı yapılır.', 40.918, 38.392, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('8ccd6655-cf1d-46f5-ac79-3b1e24f571a2', null, 'Sazan Sevdalısı', 'Hasanlar Baraj Gölü (Yığılca / Düzce)', 'Düzce tatlı su avcılarının vazgeçilmez adresi. Boilie yemli dip takımları ile dev Aynalı Sazan, Yayın ve Tatlı Su Kefali avlanabilir.', 40.962, 31.328, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('8cd00097-d19b-4341-92c5-73a8c5daad0d', null, 'Kuşadası Reis', 'Aydın Kuşadası Marina Mendireği', 'Ege liman giriş alanı. Gece EGI kalamar zokaları, gündüz canlı sülünes ve madya yem ile iri Çupra ve Karagöz avlanır.', 37.865, 27.258, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('8deac826-e477-4d8c-b65a-5b19d05a8131', null, 'İnceburun Kıyı Olta', 'Sinop İnceburun Deniz Kayalıkları', 'Türkiyenin en kuzey noktası. Akıntılı derin kaya yapısı ile trofe Palamut, Lüfer, Torik ve dev İstavritlerin av merkezidir.', 42.105, 34.935, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('92b2f6c1-9642-4724-87c5-6de7acc928c5', null, 'Porsuk Av Grubu', 'Eskişehir Porsuk Baraj Gölü', 'Eskişehir bölgesinin 1 numaralı tatlı su av alanı. Maket silikon balıklar ile Turna ve Sudak, dip oltasıyla Sazan alınır.', 39.645, 30.342, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('98684660-fd3d-4acf-a84f-57e9e6a0f534', null, 'Ahmet Yılmaz', 'Sarayburnu Akıntı Burnu', 'İstavrit ve lüfer için Boğazın en verimli meralarından biridir. Ağır kurşun arkası rapala tavsiye edilir.', 41.0175, 28.9833, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:30:39.954133+00'), ('9ce38254-0808-488e-a3fb-1e6a2f4b4947', null, 'Akdeniz Reis', 'Antalya Falezler Kayalıkları & Konyaaltı', 'Akdenizin dik falez kaya yapısı. Jigging ve canlı yemli takımlarla trofe Kuzu (Greater Amberjack), Akya, Lagos (Grida) ve Baracuda avı yapılır.', 36.872, 30.695, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('9e44e5da-bdea-4246-be45-cff790714ab8', null, 'Ordu Boztepe Kıyısı', 'Ordu Merkez Balıkçı Barınağı Mendireği', 'Ordu sahil şeridinin en aktif mera noktası. İstavrit çapari, mezgit dip oltası ve sonbaharda kaşıkla palamut çekilir.', 40.988, 37.885, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('a0a2e243-6099-44d9-8721-d448d675ca9b', null, 'Eber Göleti Olta', 'Eber Gölü Sazlık Alanı (Afyonkarahisar)', 'Geniş sazlık göl ekosistemi. At-çek kaşıklar ile Turna, yemli mısır takımları ile Aynalı Sazan ve Kızılkanat avlanır.', 38.612, 31.185, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('a3331ef3-fc1a-43e7-a337-6031588c6d7b', null, 'Kocaali Kıyı Olta', 'Kocaali Sahili Plaj Kırmalığı (Sakarya)', 'Geniş kumluk sahil şeridi. Surfcasting dip takımı, gezer kurşun ve boru kurdu ile kalkan, mırmır ve mermer balığı alır.', 41.062, 30.854, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('aba629ae-5a26-47ca-9281-4332ec077c2e', null, 'Kıyı Oltacısı', 'Şile Liman Arkası Kayalıklar', 'Levrek ve eşkina için harika bir gece merasıdır. Yemli karides ve boru kurdu çalışır.', 41.1764, 29.6105, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:33:33.878912+00'), ('ae188fad-85e4-4c82-a791-9bf1cfa363a2', null, 'İğneada Kaptan', 'Kırklareli İğneada Limanı & Longoz Ağzı', 'Batı Karadenizin en bakir meralarından biri. Yemli takımlarla kışın Kalkan, baharda spin sahtelerle Levrek ve Palamut yakalanır.', 41.876, 27.985, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('af594645-3e14-4425-affd-df35a3110872', null, 'Yeşilköy Kıyı Olta', 'İstanbul Yeşilköy Çiroz Sahili', 'Marmara Denizi kumluk ve kırmalık sahil yapısı. Gece yemli boru kurdu ve teke ile trofe Mırmır, Eşkina ve Karagöz yapar.', 40.9575, 28.825, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('b06ac89a-e182-4991-9070-02fdc8b68431', null, 'Borçka Karagöl Doğa', 'Artvin Borçka Karagöl Tabiat Parkı', 'Doğu Karadenizin yüksek irtifa doğa harikası gölü. Micro LRF kaşıkları ile Doğal Kırmızı Benekli Alabalık avı merası.', 41.365, 41.852, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('b630d4f6-a518-44ca-8fc7-21c6d9b019a2', null, 'Ege Çupracı', 'İzmir Urla İskele Mendirek Ucu', 'Ege denizinin en zengin çupra ve kalamar meralarından biri. Yemli gezer kurşunlu boru kurdu ile trofe Çupra, gece EGI zokaları ile Kalamar alınır.', 38.3621, 26.7654, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('b6932eaf-71c9-4522-ab80-f387a0e9cb02', null, 'Seben Trofe Grubu', 'Seben Baraj Gölü (Bolu)', 'Bolu bölgesinin en büyük su rezervuarı. Botla ve kıyıdan uzun mesafeli dip atışları ile trofe sazan ve dev yayın balıkları hedeflenir.', 40.4215, 31.572, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('b813cffd-492b-4f2e-b459-088a258f3a88', null, 'Foça Olta Kulübü', 'İzmir Eski Foça İngiliz Burnu Kayalıkları', 'Derin kırmalık kaya yapısı. Yemli takımlarla Karagöz, Eşkina ve Sargoz, LRF silikonları ile iri İstavrit ve Mırmır avı için mükemmeldir.', 38.672, 26.741, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('bc507bc0-2f41-4316-8459-57fddc4f9a7e', null, 'Adana Karataş Olta', 'Adana Karataş Liman Mendireği', 'Çukurova sahil şeridi merkez mera noktası. Ağır surfcasting takımları ile Çupra, Akya, Lahos ve gece sahte balıkla Levrek alır.', 36.572, 35.378, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('c69912b2-d548-4d2a-9592-9f39faaf65e5', null, 'Doğa Balıkçısı', 'Bolu Gölcük Tabiat Parkı Sahili (Bolu)', 'Sakin çam ormanlarıyla çevrili göl. Şamandıralı yemli takımlar ile Aynalı Sazan ve Kızılkanat avcılığı için eşsiz atmosfer.', 40.655, 31.625, 'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('cc75e0db-ed1e-4b8e-8bb3-fa592b7250e2', null, 'Alaçatı Kaptan', 'İzmir Çeşme Alaçatı Port Mendireği', 'Sığ kumluk ve kayalık geçiş alanı. Spin silikon sahteler ile trofe Deniz Levreği, su üstü maketler ile Akya ve Kalamar avcılığı yapılır.', 38.258, 26.375, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('cc792009-35f3-4d6f-9b10-7d12c439d987', null, 'Üsküdar Reis', 'İstanbul Üsküdar Paşalimanı Kayalıkları', 'Anadolu yakasının en hareketli mera noktalarından biridir. İstavrit çapari ve gece yemli takımlarla çinekop, sarıkanat ve eşkina verir.', 41.0325, 29.022, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('d0c4e78f-8427-44d5-9f79-c10eae9a1519', null, 'Marmaris Kaptan', 'Muğla Marmaris Yalancıboğaz Kayalıkları', 'Derin deniz kanyon geçişi. Slow jigging ve canlı yemli dip oltası ile trofe Grida (Lagos), Akya ve Kuzu balığı avı yapılır.', 36.815, 28.302, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:33:58.353644+00'), ('d21c7267-fb39-4b19-8712-9dc339915c11', null, 'Karasulu Kaptan', 'Karasu Liman Mendirek Ucu (Sakarya)', 'Sakarya bölgesinin en popüler tuzlu su merası. Ağır surfcast takımları ile istavrit çapari, kışın kalkan ve zargana avı çok verimlidir.', 41.1185, 30.689, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('d313b5c7-0fba-489b-9ab1-9c927772ad51', null, 'Sakarya Nehirci', 'Sakarya Nehri Karasu Yenimahalle Ağzı (Sakarya)', 'Sakarya nehrinin denize döküldüğü nokta. Gece zoka ve silikon sahtelerle trofe Deniz Levreği (Spin) ve nehir içlerinde Yayın avı yapılır.', 41.122, 30.655, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('d4a9193f-cf8c-46f2-a267-7ea4304224c2', null, 'Karakaya Baraj Olta', 'Karakaya Baraj Gölü (Malatya)', 'Doğu Anadolunun en zengin tatlı su havzası. Boilie ve küspe düzenekleri ile Aynalı Sazan, dip takımlarıyla dev Yayın balığı çekilir.', 38.485, 38.421, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('d8c2102c-3f13-4827-960f-c6fb93595891', null, 'Caner Balıkçı', 'Galata Köprüsü Haliç Tarafı', 'Çinekop ve istavrit avı için klasiktir. Akşam saatlerinde çapari oldukça verimlidir.', 41.02, 28.9731, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 08:41:47.904397+00'), ('dba851e6-ade0-4671-98fc-a0f91c9b3e95', null, 'Çınarcık Kaptan', 'Yalova Çınarcık Mendirek Ucu', 'Marmara Körfez giriş noktası. Sonbaharda gece EGI zokalar ile Kalamar, gündüz yemli gezer kurşunlu takımlarla Çupra ve İstavrit avlanır.', 40.644, 29.118, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('df9106d2-3f61-4fa9-bccf-32a6586a72e4', null, 'Alanya Olta Grubu', 'Antalya Alanya Kalealtı Mendirek Kayalıkları', 'Tarihi Alanya kalesi altı derin sular. Su üstü popper ve sahtelerle Akya, gece zoka takımlarıyla Baracuda ve Çupra avı verimlidir.', 36.535, 31.998, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('e1a7b038-a93c-450c-9646-69e3db75112c', null, 'Amasra Sevdalısı', 'Bartın Amasra Küçük Liman Mendireği', 'Tarihi Amasra kalesi altındaki kayalık mera. İstavrit çapari, zargana ipeği ve gece boru kurdu ile Karagöz ve Eşkina verir.', 41.751, 32.387, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('e4cc59fa-f013-4102-b319-a056038f7e77', null, 'Hopa Liman Kıyısı', 'Artvin Hopa Liman Mendirek Ucu', 'Doğu Karadeniz sınır noktası. Çapari ile palamut, zargana ipeği ile zargana ve dip takımları ile zengin mezgit çıkar.', 41.412, 41.428, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('e6dbd8bf-344b-4870-9b33-819a58e1ba40', null, 'Fırat Sevdalısı', 'Keban Baraj Gölü (Elazığ)', 'Fırat nehri üzerindeki dev baraj rezervuarı. Ağır kaşıklar ve canlı yemli montajlar ile dev Fırat Turnası, Yayın ve Şabut balığı yakalanır.', 38.802, 38.745, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('ea5fbc59-1f6d-4646-aba6-c4176d729ef4', null, 'İznik Sazan Kulübü', 'İznik Gölü Göllüce & Gölyaka Sahili (Bursa)', 'Marmaranın en büyük doğal tatlı su gölü. Boilie yemli dip oltaları ile 20kg+ trofe Aynalı Sazan, gece canlı yemle dev Yayın çekilir.', 40.432, 29.512, 'https://images.unsplash.com/photo-1439853949127-fa647821eba0?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('eac9110d-0ddc-4bd5-af45-296e0a20e784', null, 'Birecik Nehir Olta', 'Şanlıurfa Birecik Fırat Nehri Kıyısı', 'Tarihi Fırat nehrinin akıntılı suları. Ağır dip montajları ile Şabut Balığı, Fırat Turnası ve nehir Yayın balığı avcılığı yapılır.', 37.028, 37.975, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('ebf41b64-1ec3-4713-b60c-5c91dfe7fc74', null, 'Mersin Kıyıcısı', 'Mersin Taşucu Liman Mendirek Ucu', 'Güney Akdenizin en zengin çupra ve lagos merası. Yemli canlı boru kurdu ve madya ile trofe Çupra, gezer kurşunla Lagos ve Akya çıkar.', 36.315, 33.884, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('f473cb09-2695-4141-bd72-9088b476d4bd', null, 'Çayeli Kıyı Olta', 'Rize Çayeli Mendirek & Fırtına Ağzı', 'Fırtına Deresinin denize birleştiği nokta. Spin silikon sahteler ile Deniz Alası ve trofe Deniz Levreği avlanır.', 41.093, 40.742, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('f4b8b1de-da25-4a7f-b45d-0aa92788d4d6', null, 'Melen Balıkçısı', 'Büyük Melen Ağzı & Deniz Birleşimi (Düzce)', 'Melen Nehrinin Karadeniz ile buluştuğu acı su alanı. Dalgalı havalarda sahte balık (Spin) ile harika Deniz Levreği ve kefal avı verir.', 41.0715, 31.002, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:30:44.040387+00'), ('f4ecb99f-6c10-4fb5-8397-023fca367742', null, 'Nallıhan Turna Grubu', 'Sarıyar Baraj Gölü (Nallıhan / Ankara)', 'Kızılırmak ve Sakarya nehirlerinin beslediği baraj. Yayın, Sazan ve silikon yemli at-çek ile Sudak avı yapılır.', 40.045, 31.621, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:36:31.269815+00'), ('f608d81f-ca25-43c0-bb9e-80af599f3e33', null, 'Caner Balıkçı', 'Galata Köprüsü Haliç Tarafı', 'Çinekop ve istavrit avı için klasiktir. Akşam saatlerinde çapari oldukça verimlidir.', 41.02, 28.9731, 'https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:33:33.878912+00'), ('fbfadf7e-71b5-43ff-965e-e408aa3c8050', null, 'Kıyı Oltacısı', 'Şile Liman Arkası Kayalıklar', 'Levrek ve eşkina için harika bir gece merasıdır. Yemli karides ve boru kurdu çalışır.', 41.1764, 29.6105, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 11:30:39.954133+00'), ('fd08196f-f3df-4732-936e-6866d47690e9', null, 'Boğaz Oltacısı', 'İstanbul Arnavutköy Akıntı Burnu', 'Boğazın en güçlü akıntısına sahip efsanevi lüfer ve çinekop merası. 150-200gr ağır kurşun arkası rapala ve silikon yemle palamut ve lüfer alınır.', 41.0678, 29.0435, 'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00'), ('fe69f438-a260-48eb-9be0-3c36f12d7007', null, 'Kaş Kaptan', 'Antalya Kaş İnceboğaz Kayalıkları', 'Derin kanyon deniz yapısı. Slow jigging ve shore jigging ile Akya, Lagos, Melanur ve gece EGI zokalar ile dev Kalamar avlanır.', 36.195, 29.638, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:34:14.350318+00'), ('fef20127-b015-452d-ab33-79e5a89b194a', null, 'Tarabya Balıkçısı', 'İstanbul Tarabya Otel İskele Önü', 'Derin suyu ve sakin akıntısıyla palamut ve istavrit avında çok popülerdir. Uzun olta ve kaşık çalışır.', 41.139, 29.056, 'https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=800&q=80', '2026-07-23 14:32:59.751485+00');